using UnityEngine;
using UnityEngine.UI;
using UnityEditor;

public class AdjustCookingUIV2
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        GameObject panelGO = GameObject.Find("PanelMemasakV2");
        if (panelGO == null) 
        {
            var canvases = Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None);
            foreach (var c in canvases)
            {
                var p = c.transform.Find("PanelMemasakV2");
                if (p != null) { panelGO = p.gameObject; break; }
            }
        }

        if (panelGO == null) return "ERROR: PanelMemasakV2 tidak ditemukan.";

        // 1. Perbesar font MEMASAK
        var headerGO = panelGO.transform.Find("HeaderTitle");
        if (headerGO != null)
        {
            var txt = headerGO.GetComponent<Text>();
            if (txt != null) 
            {
                txt.fontSize = 48;
                sb.AppendLine("[OK] Ukuran font Header diperbesar menjadi 48.");
            }
        }

        // 2. Tambahkan tulisan "Resep Makanan"
        var existingLeftHeader = panelGO.transform.Find("TxtLeftHeader");
        if (existingLeftHeader != null) Object.DestroyImmediate(existingLeftHeader.gameObject);

        Font fontPoppins = AssetDatabase.LoadAssetAtPath<Font>("Assets/Font/Poppins-Light.ttf");

        GameObject leftHeaderGO = new GameObject("TxtLeftHeader");
        leftHeaderGO.transform.SetParent(panelGO.transform, false);
        RectTransform lhRT = leftHeaderGO.AddComponent<RectTransform>();
        lhRT.anchorMin = new Vector2(0.02f, 0.88f);
        lhRT.anchorMax = new Vector2(0.48f, 0.95f);
        lhRT.offsetMin = Vector2.zero;
        lhRT.offsetMax = Vector2.zero;

        Text lhTxt = leftHeaderGO.AddComponent<Text>();
        lhTxt.text = "Resep Makanan";
        lhTxt.font = fontPoppins;
        lhTxt.fontSize = 24;
        lhTxt.alignment = TextAnchor.MiddleLeft;
        lhTxt.color = new Color(0.9f, 0.85f, 0.7f);
        sb.AppendLine("[OK] Teks 'Resep Makanan' ditambahkan.");

        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        return sb.ToString();
    }
}
